<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID(); $available=get_post_meta($id,'_ikai_available',true); if($available==='')$available='1'; ?>
<main class="container"><div class="single-product"><div class="single-product-image"><?php if(has_post_thumbnail()) the_post_thumbnail('large'); else echo '<div class="image-placeholder" style="min-height:380px">Product image</div>'; ?></div>
<div class="single-product-content"><div class="eyebrow">Ikai.One product</div><h1><?php the_title(); ?></h1><div class="price"><?php echo esc_html(ikai_product_price($id)); ?></div><div class="availability <?php echo $available==='1'?'':'unavailable'; ?>"><?php echo $available==='1'?'Available to order':'Currently unavailable'; ?></div>
<div class="product-description"><?php the_content(); ?></div>
<?php $sku=get_post_meta($id,'_ikai_sku',true); if($sku): ?><p class="product-meta">SKU: <?php echo esc_html($sku); ?></p><?php endif; ?>
<?php if($available==='1'): ?><form class="quantity-row" onsubmit="return false"><label for="ikai-qty">Quantity</label><input id="ikai-qty" type="number" min="1" step="1" value="1"><a class="whatsapp-button" id="ikai-order-link" target="_blank" rel="noopener" href="<?php echo esc_url(ikai_whatsapp_url($id,1)); ?>">Order on WhatsApp</a></form><script>(function(){var q=document.getElementById('ikai-qty'),a=document.getElementById('ikai-order-link');if(!q||!a)return;var base=<?php echo wp_json_encode(ikai_whatsapp_url($id,1)); ?>;q.addEventListener('input',function(){var n=Math.max(1,parseInt(q.value||'1',10)||1);var u=new URL(base);var msg=u.searchParams.get('text')||'';msg=msg.replace(/Quantity: \d+/, 'Quantity: '+n);u.searchParams.set('text',msg);a.href=u.toString();});})();</script><?php else: ?><p class="muted">This product is currently unavailable. Contact us on WhatsApp for assistance.</p><a class="whatsapp-button" target="_blank" rel="noopener" href="<?php echo esc_url(ikai_whatsapp_url()); ?>">Contact on WhatsApp</a><?php endif; ?>
</div></div></main>
<?php endwhile; get_footer(); ?>
